-- Gerado por python -m pipelines.generate_dbt; não editar manualmente.
SELECT arquivo_origem, linha_origem,
d_DT_NOTIFIC AS data_notificacao,
d_DT_SIN_PRI AS data_sintomas,
CASE WHEN n_NU_IDADE_N BETWEEN 1000 AND 3999 THEN 0 WHEN n_NU_IDADE_N BETWEEN 4000 AND 4120 THEN n_NU_IDADE_N - 4000 END AS idade_anos,
CASE WHEN TRIM(CS_SEXO) IN ('M','F','I') THEN TRIM(CS_SEXO) ELSE 'I' END AS sexo,
NULLIF(n_SG_UF, 0) AS cod_uf_ibge,
NULLIF(n_ID_MN_RESI, 0) AS cod_municipio_ibge6,
NULLIF(n_ID_RG_RESI, 0) AS cod_regional_saude,
NULLIF(n_ID_UNIDADE, 0) AS cod_unidade_cnes,
NULLIF(n_SG_UF_NOT, 0) AS cod_uf_notificacao,
NULLIF(n_ID_MUNICIP, 0) AS cod_municipio_notificacao,
NULLIF(n_ID_REGIONA, 0) AS cod_regional_notificacao,
CASE n_SG_UF WHEN 11 THEN 'RO' WHEN 12 THEN 'AC' WHEN 13 THEN 'AM' WHEN 14 THEN 'RR' WHEN 15 THEN 'PA' WHEN 16 THEN 'AP' WHEN 17 THEN 'TO' WHEN 21 THEN 'MA' WHEN 22 THEN 'PI' WHEN 23 THEN 'CE' WHEN 24 THEN 'RN' WHEN 25 THEN 'PB' WHEN 26 THEN 'PE' WHEN 27 THEN 'AL' WHEN 28 THEN 'SE' WHEN 29 THEN 'BA' WHEN 31 THEN 'MG' WHEN 32 THEN 'ES' WHEN 33 THEN 'RJ' WHEN 35 THEN 'SP' WHEN 41 THEN 'PR' WHEN 42 THEN 'SC' WHEN 43 THEN 'RS' WHEN 50 THEN 'MS' WHEN 51 THEN 'MT' WHEN 52 THEN 'GO' WHEN 53 THEN 'DF' ELSE 'NI' END AS sigla_uf,
CASE n_SG_UF WHEN 11 THEN 'Rondônia' WHEN 12 THEN 'Acre' WHEN 13 THEN 'Amazonas' WHEN 14 THEN 'Roraima' WHEN 15 THEN 'Pará' WHEN 16 THEN 'Amapá' WHEN 17 THEN 'Tocantins' WHEN 21 THEN 'Maranhão' WHEN 22 THEN 'Piauí' WHEN 23 THEN 'Ceará' WHEN 24 THEN 'Rio Grande do Norte' WHEN 25 THEN 'Paraíba' WHEN 26 THEN 'Pernambuco' WHEN 27 THEN 'Alagoas' WHEN 28 THEN 'Sergipe' WHEN 29 THEN 'Bahia' WHEN 31 THEN 'Minas Gerais' WHEN 32 THEN 'Espírito Santo' WHEN 33 THEN 'Rio de Janeiro' WHEN 35 THEN 'São Paulo' WHEN 41 THEN 'Paraná' WHEN 42 THEN 'Santa Catarina' WHEN 43 THEN 'Rio Grande do Sul' WHEN 50 THEN 'Mato Grosso do Sul' WHEN 51 THEN 'Mato Grosso' WHEN 52 THEN 'Goiás' WHEN 53 THEN 'Distrito Federal' ELSE 'Não Informado' END AS nome_estado,
CASE n_SG_UF WHEN 11 THEN 'Norte' WHEN 12 THEN 'Norte' WHEN 13 THEN 'Norte' WHEN 14 THEN 'Norte' WHEN 15 THEN 'Norte' WHEN 16 THEN 'Norte' WHEN 17 THEN 'Norte' WHEN 21 THEN 'Nordeste' WHEN 22 THEN 'Nordeste' WHEN 23 THEN 'Nordeste' WHEN 24 THEN 'Nordeste' WHEN 25 THEN 'Nordeste' WHEN 26 THEN 'Nordeste' WHEN 27 THEN 'Nordeste' WHEN 28 THEN 'Nordeste' WHEN 29 THEN 'Nordeste' WHEN 31 THEN 'Sudeste' WHEN 32 THEN 'Sudeste' WHEN 33 THEN 'Sudeste' WHEN 35 THEN 'Sudeste' WHEN 41 THEN 'Sul' WHEN 42 THEN 'Sul' WHEN 43 THEN 'Sul' WHEN 50 THEN 'Centro-Oeste' WHEN 51 THEN 'Centro-Oeste' WHEN 52 THEN 'Centro-Oeste' WHEN 53 THEN 'Centro-Oeste' ELSE 'Não Informado' END AS regiao_brasil,
CASE n_SG_UF_NOT WHEN 11 THEN 'RO' WHEN 12 THEN 'AC' WHEN 13 THEN 'AM' WHEN 14 THEN 'RR' WHEN 15 THEN 'PA' WHEN 16 THEN 'AP' WHEN 17 THEN 'TO' WHEN 21 THEN 'MA' WHEN 22 THEN 'PI' WHEN 23 THEN 'CE' WHEN 24 THEN 'RN' WHEN 25 THEN 'PB' WHEN 26 THEN 'PE' WHEN 27 THEN 'AL' WHEN 28 THEN 'SE' WHEN 29 THEN 'BA' WHEN 31 THEN 'MG' WHEN 32 THEN 'ES' WHEN 33 THEN 'RJ' WHEN 35 THEN 'SP' WHEN 41 THEN 'PR' WHEN 42 THEN 'SC' WHEN 43 THEN 'RS' WHEN 50 THEN 'MS' WHEN 51 THEN 'MT' WHEN 52 THEN 'GO' WHEN 53 THEN 'DF' ELSE 'NI' END AS sigla_uf_notificacao,
CASE TRIM(CS_SEXO) WHEN 'M' THEN 'Masculino' WHEN 'F' THEN 'Feminino' WHEN 'I' THEN 'Ignorado' ELSE 'Ignorado' END AS descricao_sexo,
CASE n_CS_RACA WHEN 1 THEN 'Branca' WHEN 2 THEN 'Preta' WHEN 3 THEN 'Amarela' WHEN 4 THEN 'Parda' WHEN 5 THEN 'Indígena' WHEN 9 THEN 'Ignorado' ELSE 'Ignorado' END AS raca_cor,
CASE n_CS_GESTANT WHEN 1 THEN '1º Trimestre' WHEN 2 THEN '2º Trimestre' WHEN 3 THEN '3º Trimestre' WHEN 4 THEN 'Idade Gestacional Ignorada' WHEN 5 THEN 'Não Gestante' WHEN 6 THEN 'Não se aplica' WHEN 9 THEN 'Ignorado' ELSE 'Ignorado' END AS status_gestante,
CASE n_CS_ESCOL_N WHEN 0 THEN 'Analfabeto' WHEN 1 THEN '1ª a 4ª série incompleta' WHEN 2 THEN '4ª série completa' WHEN 3 THEN '5ª à 8ª série incompleta' WHEN 4 THEN 'Ensino fundamental completo' WHEN 5 THEN 'Ensino médio incompleto' WHEN 6 THEN 'Ensino médio completo' WHEN 7 THEN 'Educação superior incompleta' WHEN 8 THEN 'Educação superior completa' WHEN 9 THEN 'Ignorado' WHEN 10 THEN 'Não se aplica' ELSE 'Ignorado' END AS escolaridade,
CASE n_CLASSI_FIN WHEN 1 THEN 'Confirmado' WHEN 2 THEN 'Descartado' WHEN 8 THEN 'Inconclusivo / Em Investigação' ELSE 'Inconclusivo / Em Investigação' END AS classificacao_final,
CASE n_CRITERIO WHEN 1 THEN 'Laboratorial' WHEN 2 THEN 'Clínico-Epidemiológico' WHEN 3 THEN 'Em Investigação' ELSE 'Ignorado / Não Preenchido' END AS criterio_confirmacao,
CASE n_EVOLUCAO WHEN 1 THEN 'Cura' WHEN 2 THEN 'Óbito pelo agravo' WHEN 3 THEN 'Óbito por outras causas' ELSE 'Ignorado / Em Acompanhamento' END AS evolucao_caso,
CASE n_TPAUTOCTO WHEN 1 THEN 'Autóctone' WHEN 2 THEN 'Importado' ELSE 'Indeterminado / Ignorado' END AS tipo_autoctonia,
CASE n_DOENCA_TRA WHEN 1 THEN 'Sim' WHEN 2 THEN 'Não' ELSE 'Ignorado' END AS doenca_trabalho,
1 AS qt_notificacoes,
IF(n_CLASSI_FIN = 1, 1, 0) AS fl_confirmado,
IF(n_CLASSI_FIN = 2, 1, 0) AS fl_descartado,
IF(n_CS_GESTANT IN (1,2,3,4), 1, 0) AS fl_gestante,
IF(n_EVOLUCAO = 2, 1, 0) AS fl_obito_zika,
CASE WHEN DATEDIFF(d_DT_NOTIFIC, d_DT_SIN_PRI) BETWEEN 0 AND 365 THEN DATEDIFF(d_DT_NOTIFIC, d_DT_SIN_PRI) END AS qt_dias_atraso_notif,
CASE WHEN DATEDIFF(d_DT_ENCERRA, d_DT_NOTIFIC) BETWEEN 0 AND 365 THEN DATEDIFF(d_DT_ENCERRA, d_DT_NOTIFIC) END AS qt_dias_encerramento
FROM {{ ref('int_zika_tipificada') }} WHERE d_DT_NOTIFIC IS NOT NULL
